<div class="page-actions"><p class="text-muted mb-0">Administra vecinos, operadores, organismos y autoridades.</p><button class="btn btn-primary" data-modal-open="userModal">+ Crear usuario</button></div><div class="card table-card"><div class="table-responsive"><table class="table"><thead><tr><th>Usuario</th><th>Rol</th><th>Comuna</th><th>Contacto</th><th>Estado</th><th>Último ingreso</th></tr></thead><tbody><?php foreach($users as $user):?><tr><td><strong><?= e($user['name']) ?></strong><small class="d-block text-muted"><?= e($user['email']) ?></small></td><td><?= e($user['role_name']) ?></td><td><?= e($user['commune_name']?:'Global') ?></td><td><?= e($user['phone']?:'—') ?></td><td><form method="post" action="<?= url('administracion/usuarios/'.$user['id'].'/estado') ?>"><?= csrf_field() ?><select class="form-select form-select-sm" name="status" onchange="this.form.submit()" <?= $user['id']==auth()['id']?'disabled':'' ?>><option value="activo" <?= $user['status']==='activo'?'selected':'' ?>>Activo</option><option value="pendiente" <?= $user['status']==='pendiente'?'selected':'' ?>>Pendiente</option><option value="suspendido" <?= $user['status']==='suspendido'?'selected':'' ?>>Suspendido</option></select></form></td><td><?= $user['last_login_at']?e(date('d/m/Y H:i',strtotime($user['last_login_at']))):'Nunca' ?></td></tr><?php endforeach;?></tbody></table></div></div>
<div class="modal" id="userModal" hidden><div class="modal-dialog"><div class="modal-content"><div class="modal-header"><h2>Crear usuario</h2><button data-modal-close>×</button></div><form method="post" action="<?= url('administracion/usuarios') ?>"><?= csrf_field() ?><div class="modal-body"><div class="row g-3"><div class="col-md-6"><label class="form-label">Nombre</label><input class="form-control" name="name" required></div><div class="col-md-6"><label class="form-label">Correo</label><input type="email" class="form-control" name="email" required></div><div class="col-md-6"><label class="form-label">Teléfono</label><input class="form-control" name="phone"></div><div class="col-md-6"><label class="form-label">Rol</label><select class="form-select" name="role_id"><?php foreach($roles as $role):?><option value="<?= $role['id'] ?>"><?= e($role['name']) ?></option><?php endforeach;?></select></div><?php if(auth()['role_slug']==='superadmin'):?><div class="col-12"><label class="form-label">Comuna</label><select class="form-select" name="commune_id"><?php foreach($communes as $commune):?><option value="<?= $commune['id'] ?>"><?= e($commune['name']) ?></option><?php endforeach;?></select></div><?php endif;?><div class="col-12"><label class="form-label">Contraseña temporal</label><input type="password" minlength="8" class="form-control" name="password" required></div></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-modal-close>Cancelar</button><button class="btn btn-primary">Crear usuario</button></div></form></div></div></div>

